// Original study guides (2025 MDM spec subsections). Generated by tools/guides/build_guides.py
window.GUIDES=[{"code": "1.A", "title": "Engineering Terms, Symbols, and Drawings", "weak": true, "concepts": ["Orthographic views: US practice is third-angle projection. The top view sits above the front view and the right-side view sits to its right. First-angle (ISO-E) mirrors that layout.", "Section views show internal features. Full section: the cutting plane goes all the way through and the cut surface is hatched. Half section: one quarter is removed. Broken-out, revolved and removed sections are local variants.", "Dimension notation: a boxed dimension is BASIC (theoretically exact; the tolerance comes from a feature control frame). A dimension in parentheses is REFERENCE (information only, not inspected).", "GD&T (ASME Y14.5) has five families. Form (flatness, straightness, circularity, cylindricity) never takes a datum. Orientation (perpendicularity, parallelism, angularity), location (position, concentricity, symmetry) and runout (circular, total) need datums. Profile can go either way.", "Material conditions: MMC is the condition with the most material (smallest hole, largest shaft). LMC is the opposite. RFS is the default. A bonus tolerance applies when a feature departs from MMC and the MMC modifier is used.", "Virtual condition (VC) is the worst-case boundary. Shaft: VC = MMC + geometric tolerance. Hole: VC = MMC − geometric tolerance. VC sets the size of functional gauges and the mating clearance."], "formulas": [["Bonus tolerance", "Total position tol = stated tol + |actual size − MMC size|", "valid only with the Ⓜ modifier; sizes in in or mm"], ["Virtual condition (external feature)", "VC = MMC + geometric tol", "shaft/pin"], ["Virtual condition (internal feature)", "VC = MMC − geometric tol", "hole"], ["Position from coordinates", "Diametral position error = 2·√(Δx² + Δy²)", "Δx, Δy = measured deviation from the true position"]], "keywords": ["third angle projection", "section view", "GD&T", "position tolerance", "maximum material condition", "virtual condition", "datum"], "examples": [{"title": "Bonus tolerance and position check", "problem": "A Ø0.500 +0.006/−0.000 in hole has position tolerance Ø0.010 at MMC. A hole measures Ø0.504, and its axis is 0.003 in off in x and 0.004 in off in y. Is it acceptable?", "steps": ["MMC of the hole = smallest size = 0.500 in.", "Bonus = 0.504 − 0.500 = 0.004 in, so the allowed position = 0.010 + 0.004 = 0.014 in (diameter zone).", "Actual diametral error = 2√(0.003² + 0.004²) = 0.010 in.", "0.010 ≤ 0.014, so the hole is acceptable."], "answer": "Acceptable (0.010 in used of 0.014 in allowed)"}, {"title": "Virtual condition of a pin", "problem": "A pin is Ø0.750 ±0.002 in with perpendicularity Ø0.003 at MMC. Find its virtual condition.", "steps": ["MMC of the pin = largest size = 0.752 in.", "VC = MMC + tol = 0.752 + 0.003 = 0.755 in."], "answer": "0.755 in"}], "traps": ["Forgetting that the MMC of a HOLE is its SMALLEST size.", "Using the radial deviation √(Δx²+Δy²) instead of the diametral 2√(Δx²+Δy²).", "Adding a bonus tolerance when the frame has no Ⓜ modifier (RFS gives no bonus).", "Mixing up first-angle and third-angle view placement."], "cheat": ["3rd angle: top view above, right view to the right", "Boxed = basic; (x) = reference", "Form tolerances take no datum", "Hole MMC = smallest; shaft MMC = largest", "Bonus = |actual − MMC| (Ⓜ only)", "Position error = 2√(Δx²+Δy²)", "VC shaft = MMC + tol; VC hole = MMC − tol"], "area": 1}, {"code": "1.B", "title": "Project Management and Economic Analysis", "weak": true, "concepts": ["Time value of money: move every cash flow to the same point in time (P, F or A) at the interest rate i before you compare.", "Mutually exclusive alternatives: pick the best PW, AW or EUAC. With unequal lives, use annual worth, or PW over the least common multiple of the lives.", "Sunk costs are irrelevant. Only future cash flows that differ between alternatives count.", "Break-even: the volume at which revenue equals total cost. Payback ignores the time value of money and anything after payback.", "Depreciation: straight line D = (P − S)/n. MACRS uses table percentages. Book value = cost − accumulated depreciation.", "Project scheduling (CPM): the critical path is the LONGEST path through the network, and its activities have zero total float. Earned value: CPI = EV/AC, SPI = EV/PV (above 1 is good)."], "formulas": [["Single payment", "F = P(1+i)ⁿ ; P = F(1+i)⁻ⁿ", "i per period, n periods"], ["Uniform series PW", "P = A[(1+i)ⁿ−1]/[i(1+i)ⁿ]", "A at the end of each period"], ["Capital recovery", "A = P·i(1+i)ⁿ/[(1+i)ⁿ−1]", "(A/P,i,n)"], ["Sinking fund", "A = F·i/[(1+i)ⁿ−1]", "(A/F,i,n)"], ["EUAC", "EUAC = P(A/P) − S(A/F) + annual O&M", "S = salvage"], ["Break-even", "N = Fixed cost/(price − variable cost per unit)", ""], ["Effective rate", "i_eff = (1 + r/m)^m − 1", "r nominal, m compoundings/yr"], ["Earned value", "CPI = EV/AC ; SPI = EV/PV", ""]], "keywords": ["interest factor tables", "capital recovery", "sinking fund", "equivalent uniform annual cost", "break-even", "depreciation", "critical path"], "examples": [{"title": "EUAC of a machine", "problem": "A machine costs $50,000, lasts 10 years, has a $8,000 salvage value and $3,000/yr O&M. At i = 8%, find its EUAC.", "steps": ["(A/P,8%,10) = 0.14903; (A/F,8%,10) = 0.06903.", "EUAC = 50,000(0.14903) − 8,000(0.06903) + 3,000 = $9,899/yr."], "answer": "≈ $9,899/yr"}, {"title": "Break-even volume", "problem": "Fixed cost $90,000/yr, price $45/unit, variable cost $27/unit. Find the break-even volume.", "steps": ["N = 90,000/(45 − 27) = 5,000 units/yr."], "answer": "5,000 units/yr"}], "traps": ["Using a nominal rate as if it were the effective rate when compounding is monthly.", "Treating salvage as a cost (it is a credit, so subtract it).", "Comparing PW of alternatives with unequal lives over their own lives.", "Including sunk costs in a replacement study.", "Calling the path with the most activities the critical path (it is the longest in time)."], "cheat": ["(A/P) = i(1+i)ⁿ/[(1+i)ⁿ−1]", "(A/F) = i/[(1+i)ⁿ−1] = (A/P) − i", "(P/A) = 1/(A/P)", "EUAC = P(A/P) − S(A/F) + O&M", "Break-even N = FC/(p − v)", "SL depreciation (P−S)/n", "Critical path = longest, zero float"], "area": 1}, {"code": "1.C", "title": "Design Methodology", "weak": true, "concepts": ["The design process runs: define requirements → generate concepts → analyze and select (decision matrix) → detail design → prototype and test → release. It iterates.", "Verification asks 'did we build it right?' (does it meet the spec). Validation asks 'did we build the right thing?' (does it meet the user's need).", "FMEA rates each failure mode for Severity, Occurrence and Detection (1–10). RPN = S×O×D ranks the actions. A high severity alone also gets attention.", "Factor of safety n = strength/stress (or capacity/load). Reliability-based design uses distributions instead of a single n.", "Reliability: series R = ΠRᵢ; parallel (redundant) R = 1 − Π(1 − Rᵢ). Constant failure rate: R(t) = e^(−λt), MTBF = 1/λ.", "Root-cause failure analysis: preserve the evidence → fractography (beach marks show fatigue, a cup-cone shows ductile overload) → root cause → corrective action → verify."], "formulas": [["Factor of safety", "n = S/σ (or allowable load/actual load)", ""], ["Series reliability", "R_s = R₁R₂…Rₙ", ""], ["Parallel reliability", "R_p = 1 − (1−R₁)(1−R₂)…", ""], ["Exponential reliability", "R(t) = e^(−λt); MTBF = 1/λ", "λ in failures/h"], ["FMEA", "RPN = S × O × D", "each 1–10"]], "keywords": ["factor of safety", "reliability series parallel", "FMEA", "failure rate", "design process"], "examples": [{"title": "System reliability", "problem": "Pump A (R = 0.95) feeds two redundant valves in parallel (each R = 0.90), then a controller (R = 0.98). Find the system reliability.", "steps": ["Valve pair: 1 − (0.10)² = 0.99.", "System: 0.95 × 0.99 × 0.98 = 0.9217."], "answer": "0.922"}, {"title": "Exponential life", "problem": "A component has λ = 2×10⁻⁵ failures/h. Find R at 10,000 h and the MTBF.", "steps": ["R = e^(−0.2) = 0.8187.", "MTBF = 1/λ = 50,000 h."], "answer": "R ≈ 0.819; MTBF = 50,000 h"}], "traps": ["Adding reliabilities, or multiplying them for a parallel set.", "Swapping verification and validation.", "Thinking a high RPN is the only trigger (a severity of 9–10 is always critical)."], "cheat": ["Series: multiply R", "Parallel: 1 − Π(1−R)", "R = e^(−λt), MTBF = 1/λ", "RPN = S·O·D", "n = strength/stress", "Verify = spec; validate = user need"], "area": 1}, {"code": "1.D", "title": "Physical Properties of Materials", "weak": true, "concepts": ["Tension test: the elastic slope is E, then the 0.2% offset gives yield Sy, the peak gives the ultimate Su, then necking and fracture. Ductility is measured by %elongation or %reduction of area.", "True stress σ_T = σ(1+ε) and true strain ε_T = ln(1+ε) hold up to necking (constant volume). Strain hardening: σ_T = Kε_Tⁿ, and necking starts at ε_T = n.", "Resilience (elastic energy per volume) u_r = Sy²/2E. Toughness is the area under the whole curve, approximately (Sy+Su)/2·ε_f.", "Hardness tracks strength for steels: Su ≈ 0.5·HB ksi (3.45·HB MPa).", "Fe–C diagram: eutectoid 0.76% C at 727 °C (pearlite). Hypoeutectoid steels hold proeutectoid ferrite plus pearlite; use the lever rule. Quenching gives martensite and tempering restores toughness.", "BCC metals (ferritic steels) have a ductile-to-brittle transition. FCC metals (Al, Cu, austenitic stainless) do not. Creep matters above about 0.4 T_m (absolute); the Larson–Miller parameter is LMP = T(C + log t).", "Thermal expansion: δ = αLΔT. Galvanic corrosion attacks the anode (e.g. steel against copper); avoid a small anode with a large cathode.", "Composites: the rule of mixtures E_L = E_fV_f + E_m(1−V_f) applies along the fibers (iso-strain). Across the fibers (iso-stress): 1/E_T = V_f/E_f + V_m/E_m."], "formulas": [["Hooke", "σ = Eε ; ε = δ/L", "E: psi or GPa"], ["Poisson", "ε_lat = −ν·ε_axial", "ν ≈ 0.3 for steel"], ["True stress/strain", "σ_T = σ(1+ε); ε_T = ln(1+ε)", "before necking"], ["Reduction of area", "%RA = (A₀ − A_f)/A₀ = 1 − (d_f/d₀)²", ""], ["Resilience", "u_r = Sy²/(2E)", "in-lb/in³"], ["Lever rule", "W_α = (C_eut − C₀)/(C_eut − C_α)", "wt% C"], ["Larson–Miller", "LMP = T(C + log t)", "T absolute (°R or K), t in h, C ≈ 20"], ["Thermal strain", "δ = αLΔT", "α per °F or °C"], ["Rule of mixtures", "E_L = E_fV_f + E_m(1−V_f)", ""]], "keywords": ["stress-strain diagram", "true stress", "modulus of resilience", "hardness conversion", "iron-carbon phase diagram", "lever rule", "Larson-Miller", "coefficient of thermal expansion", "galvanic series"], "examples": [{"title": "Tension test reduction", "problem": "A 0.500 in diameter steel bar (E = 30×10⁶ psi, ν = 0.29) carries 12,000 lb. Find the stress, the axial strain and the change in diameter.", "steps": ["A = π(0.5)²/4 = 0.1963 in²; σ = 12,000/0.1963 = 61,115 psi.", "ε = σ/E = 2.037×10⁻³.", "Δd = −ν·ε·d = −0.29 × 2.037×10⁻³ × 0.5 = −2.95×10⁻⁴ in (it contracts)."], "answer": "σ ≈ 61,115 psi; Δd ≈ 295 µin decrease"}, {"title": "Lever rule", "problem": "A 0.30% C steel is slowly cooled to just below 727 °C (α at 0.022% C, eutectoid at 0.76% C). Find the fraction of proeutectoid ferrite.", "steps": ["W_α′ = (0.76 − 0.30)/(0.76 − 0.022) = 0.623.", "Pearlite = 0.377."], "answer": "0.623"}, {"title": "Larson–Miller", "problem": "LMP = 38,000 (°R, h, C = 20). Find the rupture life at 1,200 °F.", "steps": ["T = 1,200 + 460 = 1,660 °R.", "log t = 38,000/1,660 − 20 = 2.892 → t = 779 h."], "answer": "≈ 779 h"}], "traps": ["Using °F or °C instead of absolute temperature in Larson–Miller.", "Using diameters instead of areas in %RA (square the diameter ratio).", "Using true stress after necking with σ(1+ε) (the formula is invalid there).", "Putting the lever-rule numerator on the wrong side (use the OPPOSITE arm).", "Expecting FCC metals to show a DBTT."], "cheat": ["σ = P/A, ε = δ/L, E = σ/ε", "σ_T = σ(1+ε), ε_T = ln(1+ε)", "%RA = 1 − (d_f/d₀)²", "u_r = Sy²/2E", "Su ≈ 0.5 HB ksi", "Eutectoid 0.76% C, 727 °C", "LMP = T_abs(20 + log t)", "δ = αLΔT", "E_L = E_fV_f + E_mV_m"], "area": 1}, {"code": "2.A", "title": "Axial Loading", "weak": true, "concepts": ["Normal stress σ = P/A acts on a section perpendicular to the load. Elongation δ = PL/(AE) for each uniform segment; add the segments of a stepped bar.", "Statically indeterminate bars: write equilibrium, then compatibility (equal deformations, or deformations that sum to a gap), then the force–deformation relations.", "Parallel members sharing a rigid plate split the load in proportion to their axial stiffness k = AE/L.", "Poisson effect: lateral strain = −ν × axial strain. Diameter change Δd = −ν·ε·d."], "formulas": [["Axial stress", "σ = P/A", "psi, MPa"], ["Elongation", "δ = PL/(AE) ; δ_total = Σ PᵢLᵢ/(AᵢEᵢ)", "in, mm"], ["Axial stiffness", "k = AE/L", ""], ["Load sharing (parallel)", "P₁ = P·k₁/(k₁+k₂)", "equal strain"], ["Poisson", "Δd = −ν(σ/E)d", ""]], "keywords": ["axial deformation PL/AE", "statically indeterminate", "compatibility", "Poisson's ratio"], "examples": [{"title": "Stepped bar", "problem": "A steel bar (E = 30×10⁶ psi) has 12 in of Ø1.5 in and 8 in of Ø1.0 in and carries 20,000 lb tension. Find the total elongation.", "steps": ["A₁ = 1.7671 in², A₂ = 0.7854 in².", "δ = (20,000/30×10⁶)(12/1.7671 + 8/0.7854) = 0.01132 in."], "answer": "0.0113 in"}, {"title": "Steel and aluminum posts", "problem": "A rigid cap sits on a steel post (A = 1.0 in², E = 30×10⁶) and an aluminum post (A = 1.5 in², E = 10×10⁶) of equal length and carries 30,000 lb. Find the steel load.", "steps": ["Compatibility: equal shortening, so the load splits in proportion to AE.", "P_s = 30,000·(30)/(30 + 15) = 20,000 lb; P_a = 10,000 lb."], "answer": "20,000 lb"}], "traps": ["Using one area for a stepped bar.", "Forgetting compatibility in indeterminate problems.", "Unit slips: kN with mm and GPa (1 GPa = 1,000 N/mm²)."], "cheat": ["σ = P/A", "δ = ΣPL/AE", "k = AE/L", "Parallel: P ∝ AE/L", "Δd = −ν(σ/E)d"], "area": 2}, {"code": "2.B", "title": "Shear and Transverse Loading", "weak": true, "concepts": ["Direct shear (pins, bolts, keys): τ = V/A_shear. Single shear uses 1 area per pin; double shear uses 2.", "Beam transverse shear: τ = VQ/(Ib). It peaks at the neutral axis and is zero at the top and bottom fibers.", "Rectangle: τ_max = 1.5V/A. Solid circle: τ_max = (4/3)V/A. Thin-walled tube: τ_max ≈ 2V/A.", "Shear flow q = VQ/I (force per length) sizes the nails, bolts or welds that join built-up beam parts."], "formulas": [["Direct shear", "τ = V/(nA)", "n = number of shear planes"], ["Transverse shear", "τ = VQ/(Ib)", "Q = first moment of the area beyond the cut"], ["Rectangle max", "τ_max = 3V/(2A)", ""], ["Circle max", "τ_max = 4V/(3A)", ""], ["Shear flow", "q = VQ/I ; fastener spacing s = F_allow/q", "lb/in"]], "keywords": ["transverse shear stress VQ/Ib", "shear flow", "double shear", "first moment of area"], "examples": [{"title": "Rectangular beam", "problem": "A 3 in × 8 in rectangular beam carries V = 9,600 lb. Find τ_max.", "steps": ["A = 24 in².", "τ_max = 1.5(9,600)/24 = 600 psi at the neutral axis."], "answer": "600 psi"}, {"title": "Clevis pin in double shear", "problem": "A Ø0.625 in pin carries 8,000 lb in double shear. Find τ.", "steps": ["A = π(0.625)²/4 = 0.3068 in².", "τ = 8,000/(2 × 0.3068) = 13,038 psi."], "answer": "13,038 psi"}], "traps": ["Using V/A (the average) when the maximum is asked.", "Forgetting double shear (2 planes).", "Using 4/3 for a rectangle or 3/2 for a circle."], "cheat": ["τ = V/(nA)", "τ = VQ/Ib", "Rect 1.5V/A; circle 4V/3A; tube 2V/A", "q = VQ/I"], "area": 2}, {"code": "2.C", "title": "Bending", "weak": true, "concepts": ["Draw shear and moment diagrams. Shear is the slope of the moment curve, so moment peaks where V = 0. Jumps happen at point loads (V) and applied couples (M).", "Flexure formula: σ = Mc/I = M/S, with tension and compression on opposite sides of the neutral axis.", "Parallel axis: I = I_c + Ad². For a composite section, find the centroid first.", "Deflection: use the handbook beam tables and superpose load cases. Simply supported with a center load: PL³/48EI. Cantilever with an end load: PL³/3EI. UDL on a simple span: 5wL⁴/384EI."], "formulas": [["Flexure", "σ = Mc/I = M/S", "S = I/c"], ["Rectangle", "I = bh³/12 ; S = bh²/6", ""], ["Circle", "I = πd⁴/64 ; S = πd³/32", ""], ["Parallel axis", "I = I_c + Ad²", ""], ["SS center load", "M_max = PL/4 ; δ = PL³/48EI", ""], ["SS UDL", "M_max = wL²/8 ; δ = 5wL⁴/384EI", ""], ["Cantilever end load", "M_max = PL ; δ = PL³/3EI", ""], ["Cantilever UDL", "M_max = wL²/2 ; δ = wL⁴/8EI", ""]], "keywords": ["flexure formula Mc/I", "shear and moment diagrams", "beam deflection tables", "section modulus", "parallel axis theorem"], "examples": [{"title": "Wood beam with UDL", "problem": "A 12 ft simple span carries 400 lb/ft. The section is 3.5 in × 9.25 in. Find σ_max.", "steps": ["M = wL²/8 = 400(12)²/8 = 7,200 ft-lb = 86,400 in-lb.", "S = bh²/6 = 49.9 in³.", "σ = M/S = 1,731 psi."], "answer": "1,731 psi"}, {"title": "Midspan deflection", "problem": "A simply supported steel beam (E = 29×10⁶ psi, I = 100 in⁴) spans 120 in with 10,000 lb at midspan. Find δ.", "steps": ["δ = PL³/48EI = 10,000(120)³/(48·29×10⁶·100) = 0.1241 in."], "answer": "0.1241 in"}], "traps": ["Leaving the moment in ft-lb while S is in in³ (multiply by 12).", "Using c = h instead of h/2.", "Taking the moment at the wrong location (max M is where V = 0).", "Mixing the cantilever and simply supported formulas."], "cheat": ["σ = Mc/I = M/S", "Rect S = bh²/6", "Max M where V = 0", "SS: PL/4, wL²/8", "δ: PL³/48EI, 5wL⁴/384EI, PL³/3EI, wL⁴/8EI", "I = I_c + Ad²"], "area": 2}, {"code": "2.D", "title": "Buckling", "weak": true, "concepts": ["Long slender columns fail by elastic buckling (Euler). Short columns fail by yielding. Intermediate columns follow the Johnson parabola.", "Effective length L_e = KL. Theoretical K: fixed–fixed 0.5, fixed–pinned 0.7, pinned–pinned 1.0, fixed–free 2.0. Design (recommended) K values are a little higher.", "Slenderness ratio = KL/r, with r = √(I/A). Compare it with the transition value C_c = √(2π²E/Sy). Above C_c use Euler; below it use Johnson.", "Always buckle about the weak axis (smallest I)."], "formulas": [["Euler load", "P_cr = π²EI/(KL)²", ""], ["Euler stress", "σ_cr = π²E/(KL/r)²", ""], ["Radius of gyration", "r = √(I/A) ; solid round r = d/4", ""], ["Transition", "C_c = √(2π²E/Sy)", ""], ["Johnson", "P_cr = A[Sy − (Sy·KL/r)²/(4π²E)]", "intermediate"]], "keywords": ["Euler buckling", "effective length factor", "slenderness ratio", "Johnson formula", "radius of gyration"], "examples": [{"title": "Pinned steel column", "problem": "A Ø1.25 in solid steel rod (E = 29×10⁶ psi, Sy = 50 ksi), 60 in long and pinned at both ends. Find P_cr.", "steps": ["r = d/4 = 0.3125 in; KL/r = 60/0.3125 = 192.", "C_c = √(2π²·29×10⁶/50,000) = 107. Since 192 > 107, use Euler.", "I = πd⁴/64 = 0.1198 in⁴; P_cr = π²EI/L² = 9,528 lb."], "answer": "9,528 lb"}], "traps": ["Using Euler for a short column (check KL/r against C_c).", "Using the strong-axis I.", "Swapping K for fixed–free (2.0) and fixed–fixed (0.5)."], "cheat": ["P_cr = π²EI/(KL)²", "K: 0.5 / 0.7 / 1 / 2", "r = √(I/A), round d/4", "C_c = √(2π²E/Sy)", "Johnson below C_c"], "area": 2}, {"code": "2.E", "title": "Torsion", "weak": true, "concepts": ["Circular shafts: τ = Tc/J peaks at the outer surface. Angle of twist θ = TL/(JG) in radians.", "Power and torque: T(in-lb) = 63,025·hp/rpm; T(ft-lb) = 5,252·hp/rpm; T(N·m) = 9,549·kW/rpm.", "Hollow shafts: J = π(D⁴ − d⁴)/32. For the same weight they carry more torque.", "Thin-walled closed tube: τ = T/(2A_m t), where A_m is the area enclosed by the mid-wall line."], "formulas": [["Torsion stress", "τ = Tc/J = 16T/(πd³) (solid)", ""], ["Polar moment", "J = πd⁴/32 ; hollow π(D⁴−d⁴)/32", ""], ["Twist", "θ = TL/(JG) [rad]", "G steel ≈ 11.5×10⁶ psi = 80 GPa"], ["Power", "T = 63,025 hp/n (in-lb)", ""], ["Thin tube", "τ = T/(2A_m t)", ""]], "keywords": ["torsion shear stress Tc/J", "angle of twist", "polar moment of inertia", "power torque speed"], "examples": [{"title": "Size a shaft for torque", "problem": "A shaft transmits 20 hp at 600 rpm with an allowable τ of 12,000 psi. Find the minimum solid diameter.", "steps": ["T = 63,025(20)/600 = 2,101 in-lb.", "d = (16T/πτ)^(1/3) = 0.962 in."], "answer": "0.962 in (use the next standard size)"}, {"title": "Twist", "problem": "Same torque on a Ø1.25 in shaft, 48 in long, with G = 11.5×10⁶ psi. Find θ.", "steps": ["J = π(1.25)⁴/32 = 0.2397 in⁴.", "θ = TL/JG = 0.0366 rad = 2.10°."], "answer": "2.10°"}], "traps": ["Leaving θ in radians when degrees are asked.", "Using I (πd⁴/64) instead of J.", "Using 5,252 (gives ft-lb) and then using in-lb."], "cheat": ["τ = 16T/πd³", "J = πd⁴/32", "θ = TL/JG (rad)", "T = 63,025 hp/n in-lb", "Thin tube τ = T/2A_m t"], "area": 2}, {"code": "2.F", "title": "Combined Loading", "weak": true, "concepts": ["Superpose stresses at one point: axial P/A, bending ±Mc/I, torsion Tc/J, transverse VQ/Ib. Find the critical point (usually the outer fiber).", "Mohr's circle: center C = (σx+σy)/2, radius R = √[((σx−σy)/2)² + τ²]. σ₁,₂ = C ± R and τ_max,in-plane = R.", "In 3-D, the absolute maximum shear = (σ_max − σ_min)/2, counting σ₃ = 0 in plane stress.", "Shaft with bending plus torsion: σ = 32M/πd³, τ = 16T/πd³, von Mises σ′ = √(σ² + 3τ²)."], "formulas": [["Principal stresses", "σ₁,₂ = (σx+σy)/2 ± √[((σx−σy)/2)² + τxy²]", ""], ["Max in-plane shear", "τ_max = √[((σx−σy)/2)² + τxy²]", ""], ["Principal angle", "tan 2θp = 2τxy/(σx−σy)", ""], ["Combined axial + bending", "σ = P/A ± Mc/I", ""], ["Shaft", "σ′ = √(σ² + 3τ²)", ""]], "keywords": ["Mohr's circle", "principal stresses", "combined stresses", "von Mises"], "examples": [{"title": "Principal stresses", "problem": "σx = 12 ksi, σy = −4 ksi, τxy = 6 ksi. Find σ₁, σ₂ and τ_max.", "steps": ["C = 4 ksi; R = √(8² + 6²) = 10 ksi.", "σ₁ = 14 ksi; σ₂ = -6 ksi; τ_max = 10 ksi."], "answer": "σ₁ = 14, σ₂ = −6, τ_max = 10 ksi"}], "traps": ["Forgetting σ₃ = 0 when σ₁ and σ₂ have the same sign (then τ_abs = σ₁/2).", "Sign errors for compressive σy.", "Using √(σ² + 4τ²) (Tresca) when von Mises is asked."], "cheat": ["C = (σx+σy)/2", "R = √[((σx−σy)/2)² + τ²]", "σ₁,₂ = C ± R", "τ_max = R (in-plane)", "σ′ = √(σ² + 3τ²)"], "area": 2}, {"code": "2.G", "title": "Static Failure", "weak": true, "concepts": ["Ductile materials: use distortion energy (von Mises, the best fit) or maximum shear stress (Tresca, conservative). Brittle materials: use maximum normal stress, Coulomb–Mohr or modified Mohr.", "von Mises plane stress: σ′ = √(σ₁² − σ₁σ₂ + σ₂²) = √(σx² − σxσy + σy² + 3τ²). n = Sy/σ′.", "Tresca: n = Sy/(σ_max − σ_min), including σ₃ = 0. Shear yield: von Mises Ssy = 0.577Sy; Tresca 0.5Sy.", "Static stress concentration: ductile materials can usually ignore Kt (local yielding relieves it). Brittle materials must apply Kt."], "formulas": [["von Mises", "σ′ = √(σ₁² − σ₁σ₂ + σ₂²) ; n = Sy/σ′", ""], ["Tresca", "n = Sy/(σ₁ − σ₃)", ""], ["Shear yield", "Ssy = 0.577Sy (DE), 0.5Sy (MSS)", ""], ["Max normal (brittle)", "n = Sut/σ₁", ""]], "keywords": ["distortion energy theory", "maximum shear stress theory", "factor of safety", "Mohr theory brittle"], "examples": [{"title": "von Mises vs Tresca", "problem": "Use σ₁ = 14 ksi and σ₂ = −6 ksi from the 2.F example, with Sy = 50 ksi. Find n by both theories.", "steps": ["σ′ = √(14² − 14(−6) + 6²) = 17.78 ksi → n = 2.81.", "Tresca: σ₁ − σ₃ = 14 − (−6) = 20 ksi → n = 2.50."], "answer": "n_DE = 2.81; n_Tresca = 2.50"}], "traps": ["Using Tresca with σ₁ − σ₂ when both are positive (σ₃ = 0 governs).", "Applying Kt to a ductile part under static load.", "Applying the brittle theories to steel."], "cheat": ["σ′ = √(σ₁² − σ₁σ₂ + σ₂²)", "Tresca n = Sy/(σmax − σmin)", "Ssy: 0.577Sy / 0.5Sy", "Brittle: Coulomb–Mohr", "Ductile static: ignore Kt"], "area": 2}, {"code": "2.H", "title": "Fatigue Failure", "weak": true, "concepts": ["The endurance limit of steel: Se′ ≈ 0.5Sut (Sut ≤ 200 ksi), or 100 ksi above that. Correct it with the Marin factors Se = ka·kb·kc·kd·ke·Se′ (surface, size, load, temperature, reliability).", "Fluctuating stress: σa = (σmax − σmin)/2, σm = (σmax + σmin)/2. Apply K_f = 1 + q(Kt − 1) to the stresses.", "Mean-stress criteria: modified Goodman 1/n = σa/Se + σm/Sut (conservative, the usual exam choice). Gerber is a parabola (better fit). ASME-elliptic uses Sy. Also check first-cycle yield: σa + σm ≤ Sy/n.", "Finite life: S-N line through (10³, f·Sut) and (10⁶, Se), with S = aN^b. Miner's rule: Σnᵢ/Nᵢ = 1."], "formulas": [["Endurance limit", "Se′ = 0.5Sut (steel)", ""], ["Surface factor", "ka = a·Sut^b (machined: a = 2.70, b = −0.265 ksi)", ""], ["Size factor", "kb = 0.879d^−0.107 (0.11–2 in)", ""], ["Fatigue Kt", "K_f = 1 + q(Kt − 1)", ""], ["Goodman", "1/n = σa/Se + σm/Sut", ""], ["Basquin", "S_f = aN^b ; b = −(1/3)log(f·Sut/Se) ; a = (f·Sut)²/Se", ""], ["Miner", "Σ nᵢ/Nᵢ = 1", ""]], "keywords": ["endurance limit", "Marin factors", "modified Goodman", "notch sensitivity", "S-N diagram", "Miner's rule"], "examples": [{"title": "Goodman factor of safety", "problem": "A machined Ø1.0 in steel shaft (Sut = 90 ksi) sees σa = 18 ksi and σm = 20 ksi (K_f already applied), in rotating bending. Find n by Goodman.", "steps": ["ka = 2.70(90)^−0.265 = 0.819; kb = 0.879(1.0)^−0.107 = 0.879.", "Se = 0.5(90)(0.819)(0.879) = 32.4 ksi.", "1/n = 18/32.4 + 20/90 → n = 1.29."], "answer": "n ≈ 1.29"}, {"title": "Fatigue stress concentration", "problem": "Kt = 2.4 and q = 0.85. Find K_f.", "steps": ["K_f = 1 + 0.85(1.4) = 2.19."], "answer": "2.19"}], "traps": ["Forgetting the Marin factors (using the raw 0.5Sut).", "Applying K_f to the strength instead of the stress (or applying it twice).", "Using σmax instead of σa and σm.", "Skipping the first-cycle yield check."], "cheat": ["Se′ = 0.5Sut", "Se = ka·kb·kc·kd·ke·Se′", "K_f = 1 + q(Kt − 1)", "σa = (max − min)/2; σm = (max + min)/2", "Goodman: 1/n = σa/Se + σm/Sut", "Miner: Σn/N = 1"], "area": 2}, {"code": "2.I", "title": "Thermal and Interference Stresses", "weak": true, "concepts": ["A fully restrained bar heated by ΔT: σ = EαΔT (compressive). If there is a gap, only the expansion beyond the gap is restrained.", "Press and shrink fits: the interface pressure p comes from the interference δ (diametral). Same material, solid shaft: p = Eδ(D_o² − d²)/(2dD_o²).", "Hub hoop stress at the bore is σ_t = p(D_o² + d²)/(D_o² − d²). Torque capacity T = πμpd²L/2. Axial force capacity F = πμpdL.", "Shrink-fit assembly: the hub temperature rise is ΔT = (δ + clearance)/(αd)."], "formulas": [["Restrained bar", "σ = EαΔT", "with gap: σ = E(αΔTL − gap)/L"], ["Interference pressure", "p = Eδ(D_o² − d²)/(2dD_o²)", "same E, solid shaft"], ["Hub bore hoop", "σ_t = p(D_o² + d²)/(D_o² − d²)", ""], ["Torque capacity", "T = πμpd²L/2", ""], ["Shrink temp", "ΔT = (δ + c)/(αd)", ""]], "keywords": ["thermal stress", "interference fit pressure", "shrink fit", "press fit torque"], "examples": [{"title": "Restrained rail", "problem": "A steel bar (E = 29×10⁶ psi, α = 6.5×10⁻⁶/°F) is fixed between walls and heated 100 °F. Find σ.", "steps": ["σ = EαΔT = 29×10⁶(6.5×10⁻⁶)(100) = 18,850 psi (compression)."], "answer": "18,850 psi"}, {"title": "Press-fit torque", "problem": "A Ø2.0 in steel shaft is pressed into a steel hub (OD 4.0 in, L = 2.5 in) with δ = 0.002 in, E = 30×10⁶ psi, μ = 0.15. Find p and T.", "steps": ["p = 30×10⁶(0.002)(16 − 4)/(2·2·16) = 11,250 psi.", "T = π(0.15)p(2²)(2.5)/2 = 26,507 in-lb."], "answer": "T ≈ 26,507 in-lb"}], "traps": ["Using a radial interference where the formula expects diametral (or vice versa).", "Ignoring the gap.", "Forgetting that thermal stress does not depend on length when the bar is fully restrained."], "cheat": ["σ = EαΔT", "p = Eδ(D_o² − d²)/(2dD_o²)", "T = πμpd²L/2", "ΔT_shrink = (δ + c)/(αd)"], "area": 2}, {"code": "3.A", "title": "Bonds (Welding, Brazing, Adhesives)", "weak": false, "concepts": ["Fillet weld strength is set by the throat: t = 0.707h for an equal-leg fillet. Shear stress τ = F/(0.707hL).", "Weld groups under torsion or bending: treat the weld as a line. Find the unit properties J_u and I_u, then J = 0.707hJ_u. Add the primary (direct) and secondary (moment) shear as vectors.", "Weld symbols (AWS A2.4): a symbol below the reference line means arrow side; above means other side. A flag means field weld, a circle means all around, and the tail carries the process or spec.", "Adhesives are strong in shear and weak in peel. Lap joint: τ_avg = F/(bL)."], "formulas": [["Fillet throat stress", "τ = F/(0.707hL)", ""], ["Weld torsion", "τ″ = Tr/J ; J = 0.707h·J_u", "circle J_u = 2πr³"], ["Weld bending", "τ = Mc/I ; I = 0.707h·I_u", "circle I_u = πr³"], ["Adhesive lap", "τ = F/(bL)", ""]], "keywords": ["fillet weld throat", "weld group polar moment", "welding symbols", "adhesive lap joint"], "examples": [{"title": "Parallel fillet welds", "problem": "Two 0.3125 in fillet welds, each 6 in long, carry 18,000 lb in shear. Find τ.", "steps": ["Throat area = 2(0.707)(0.3125)(6) = 2.651 in².", "τ = 18,000/2.651 = 6,789 psi."], "answer": "6,789 psi"}], "traps": ["Using the leg h instead of the throat 0.707h.", "Adding the primary and secondary shear as scalars instead of vectors.", "Reversing arrow side and other side on the symbol."], "cheat": ["t = 0.707h", "τ = F/(0.707hΣL)", "J = 0.707h·J_u", "Below line = arrow side"], "area": 3}, {"code": "3.B", "title": "Non-threaded Fasteners", "weak": false, "concepts": ["Pins, rivets and keys: check shear (single or double), bearing (crushing, σ_b = F/(dt)), and net-section tension of the plate, σ = F/((w − d)t).", "Keys: the force at the shaft surface is F = 2T/d. Shear τ = F/(wL); bearing on half the height σ = F/(L·h/2).", "Retaining rings, roll pins and shoulders locate parts axially."], "formulas": [["Key force", "F = 2T/d", ""], ["Key shear", "τ = F/(wL)", ""], ["Key bearing", "σ = 2F/(hL)", "square key h = w"], ["Bearing on plate", "σ_b = F/(n·d·t)", ""], ["Net section", "σ = F/((w − Σd)t)", ""]], "keywords": ["key shear", "rivet bearing stress", "pin double shear", "net section"], "examples": [{"title": "Square key length", "problem": "A 0.375 in square key on a Ø1.5 in shaft carries 4,000 in-lb. Key Sy = 60 ksi, n = 2.5, Ssy = 0.577Sy. Find the minimum L.", "steps": ["F = 2(4,000)/1.5 = 5,333 lb.", "Shear: L = Fn/(0.577·Sy·w) = 1.027 in.", "Bearing: L = Fn/(Sy·w/2) = 1.185 in. Bearing governs."], "answer": "1.19 in"}], "traps": ["Using the diameter instead of the radius in F = T/r.", "Forgetting the bearing check on half the key height."], "cheat": ["F = 2T/d", "τ = F/wL", "σ_b = 2F/hL", "net = F/((w − d)t)"], "area": 3}, {"code": "3.C", "title": "Threaded Fasteners", "weak": false, "concepts": ["Preload: F_i = 0.75A_tS_p for a reusable joint, 0.90A_tS_p for a permanent one. Torque T = KF_id with K ≈ 0.2 dry or 0.15 lubricated.", "Joint constant C = k_b/(k_b + k_m). The bolt picks up C·P of the external load and the members lose (1 − C)P. The joint separates at P₀ = F_i/(1 − C).", "Bolt fatigue: σ_a = CP/(2A_t) and σ_m = σ_a + F_i/A_t. Use Goodman with the preload line.", "Eccentric bolt groups: primary shear P/n plus secondary shear F = Mr/Σr², added as vectors."], "formulas": [["Preload", "F_i = 0.75A_tS_p (reusable)", ""], ["Torque", "T = K·F_i·d", ""], ["Joint constant", "C = k_b/(k_b + k_m)", ""], ["Bolt load", "F_b = F_i + CP", ""], ["Separation", "P₀ = F_i/(1 − C)", ""], ["Eccentric group", "F″ = Mrᵢ/Σr²", ""]], "keywords": ["bolt preload", "torque coefficient", "joint stiffness constant", "bolted joint separation", "eccentric bolt group"], "examples": [{"title": "Preload, torque and separation", "problem": "A 1/2-13 UNC grade 5 bolt (A_t = 0.1419 in², S_p = 85 ksi), reusable, K = 0.2, k_b = 3 and k_m = 10 (×10⁶ lb/in). Find F_i, T, the bolt load at P = 2,000 lb, and the separation load.", "steps": ["F_i = 0.75(0.1419)(85,000) = 9,046 lb.", "T = 0.2(9,046)(0.5) = 905 in-lb.", "C = 3/13 = 0.231; F_b = 9,046 + 0.231(2,000) = 9,508 lb.", "P₀ = 9,046/(1 − 0.231) = 11,760 lb."], "answer": "F_i ≈ 9,046 lb; T ≈ 905 in-lb; P₀ ≈ 11,760 lb"}], "traps": ["Giving the bolt the whole external load (it only takes C·P).", "Using the major-diameter area instead of A_t.", "Using 0.90 preload when the joint is reusable."], "cheat": ["F_i = 0.75A_tS_p", "T = KF_id", "C = k_b/(k_b + k_m)", "F_b = F_i + CP", "P₀ = F_i/(1 − C)"], "area": 3}, {"code": "4.A", "title": "Gears and Gear Trains", "weak": false, "concepts": ["Geometry: diametral pitch P = N/d (teeth/in) or module m = d/N (mm). Center distance = (d₁ + d₂)/2. Mating gears must share P (or m) and the pressure angle.", "Forces (spur): W_t = 33,000hp/V (V in ft/min), radial W_r = W_t·tanφ. Helical: axial W_a = W_t·tanψ.", "Train value = product of driver teeth / product of driven teeth. Planetary: use the Willis formula (n_L − n_A)/(n_F − n_A) = e.", "Bending (Lewis): σ = K_vW_tP/(FY). Wear (contact) uses the AGMA equations."], "formulas": [["Pitch", "P = N/d ; m = d/N", ""], ["Pitch-line velocity", "V = πdn/12 (ft/min)", ""], ["Tangential load", "W_t = 33,000 hp/V", ""], ["Radial", "W_r = W_t tanφ", ""], ["Helical axial", "W_a = W_t tanψ", ""], ["Lewis", "σ = K_vW_tP/(FY)", ""], ["Planetary", "(n_ring − n_arm)/(n_sun − n_arm) = −N_sun/N_ring", ""]], "keywords": ["diametral pitch", "gear forces", "Lewis bending", "gear train value", "planetary gear train"], "examples": [{"title": "Spur gear forces", "problem": "An 18T pinion with P = 6 and φ = 20° transmits 5 hp at 1,150 rpm. Find W_t and W_r.", "steps": ["d = 18/6 = 3 in; V = π(3)(1,150)/12 = 903 ft/min.", "W_t = 33,000(5)/903 = 182.7 lb; W_r = 66.5 lb."], "answer": "W_t ≈ 183 lb, W_r ≈ 66 lb"}], "traps": ["Using V in ft/s.", "Mixing up driver and driven teeth in the train value.", "Using the pressure angle for the helical thrust (use the helix angle)."], "cheat": ["P = N/d; C = (N₁ + N₂)/(2P)", "V = πdn/12", "W_t = 33,000hp/V", "W_r = W_t tanφ; W_a = W_t tanψ", "Planetary: Willis formula"], "area": 4}, {"code": "4.B", "title": "Bearings", "weak": false, "concepts": ["Rolling bearings: L₁₀ = (C/P)^a × 10⁶ revolutions, with a = 3 for ball and 10/3 for roller bearings. Hours = rev/(60n).", "Equivalent load P = XF_r + YF_a when F_a/F_r > e. Required rating C = P(L_D/L_R)^(1/a).", "Reliability adjustment (Weibull): for R ≠ 0.90, the life scales with [ln(1/R)/ln(1/0.9)]^(1/b).", "Journal bearings: Sommerfeld number S = (r/c)²μN/P; the Petroff torque estimates friction."], "formulas": [["Rating life", "L₁₀ = (C/P)^a ×10⁶ rev", ""], ["Hours", "L_h = L₁₀/(60n)", ""], ["Equivalent load", "P = XF_r + YF_a", ""], ["Required C", "C = P(L_h·60n/10⁶)^(1/a)", ""], ["Sommerfeld", "S = (r/c)²μN/P", ""]], "keywords": ["bearing L10 life", "dynamic load rating", "equivalent radial load", "Sommerfeld number"], "examples": [{"title": "Roller bearing life", "problem": "Roller bearing with C = 15,000 N, P = 4,000 N, n = 3,600 rpm. Find L₁₀ in hours.", "steps": ["L₁₀ = (15,000/4,000)^(10/3) × 10⁶ rev = 81,928,982 rev.", "Hours = rev/(60 × 3,600) = 379 h."], "answer": "379 h"}], "traps": ["Using a = 3 for roller bearings.", "Forgetting the 60 min/h.", "Using the radial load alone when thrust is present."], "cheat": ["L₁₀ = (C/P)^a 10⁶ rev", "a = 3 ball, 10/3 roller", "P = XF_r + YF_a", "h = rev/60n"], "area": 4}, {"code": "4.C", "title": "Belts, Chains, Clutches, Brakes, Power Screws", "weak": false, "concepts": ["Flat belt: T₁/T₂ = e^(μθ) at impending slip (V-belts use μ/sin(β/2)). Power = (T₁ − T₂)V.", "Chain: V = NpN_rpm/12 (ft/min). Chordal action is reduced by using more sprocket teeth.", "Disk clutch (uniform wear): T = NμF(D + d)/4. Uniform pressure gives slightly more torque. Band brake: T = (T₁ − T₂)r with T₁/T₂ = e^(μθ).", "Square-thread power screw: T_raise = (Wd_m/2)(l + πμd_m)/(πd_m − μl) + collar torque Wμ_cd_c/2. It is self-locking if πμd_m > l. Efficiency = Wl/(2πT)."], "formulas": [["Belt", "T₁/T₂ = e^(μθ) ; hp = (T₁ − T₂)V/33,000", ""], ["Open-belt length", "L = 2C + π(D + d)/2 + (D − d)²/(4C)", ""], ["Clutch (uniform wear)", "T = NμF(D + d)/4", ""], ["Screw raise", "T = (Wd_m/2)(l + πμd_m)/(πd_m − μl)", ""], ["Efficiency", "e = Wl/(2πT)", ""]], "keywords": ["belt tension ratio", "band brake", "disk clutch uniform wear", "power screw torque", "chain velocity"], "examples": [{"title": "Flat belt tensions", "problem": "A belt transmits 5 hp from a 6 in pulley at 1,150 rpm, θ = 180°, μ = 0.3. Find T₁.", "steps": ["Net force T₁ − T₂ = T/r = (63,025·5/1,150)/3 = 91.3 lb.", "e^(μθ) = e^(0.3π) = 2.566; T₁ = F·e/(e − 1) = 149.7 lb."], "answer": "150 lb"}], "traps": ["Using θ in degrees in e^(μθ).", "Forgetting the collar friction on a power screw.", "Using uniform pressure when the question says uniform wear."], "cheat": ["T₁/T₂ = e^(μθ), θ in rad", "hp = (T₁ − T₂)V/33,000", "Clutch: NμF(D + d)/4", "Screw: self-locking if πμd_m > l"], "area": 4}, {"code": "4.D", "title": "Shafts and Keys", "weak": false, "concepts": ["Design steps: loads → shear and moment diagrams → critical sections (shoulders, keyways) → fatigue size → check deflection, slopes and critical speed.", "DE-Goodman with rotating bending (M_a) and steady torque (T_m): d = {16n/π [2K_fM_a/S_e + √3K_fsT_m/S_ut]}^(1/3).", "Critical speed: ω = √(g/δ_st) for a single disk (Rayleigh for several). Keep the operating speed well away from it.", "Flywheel: ΔE = C_sIω², with C_s = (ω_max − ω_min)/ω_avg."], "formulas": [["DE-Goodman diameter", "d = {16n/π [2K_fM_a/S_e + √3K_fsT_m/S_ut]}^(1/3)", ""], ["Static torsion", "d = (16Tn/(πS_sy))^(1/3)", ""], ["Critical speed", "n_c = (30/π)√(g/δ)", "g = 386 in/s²"], ["Flywheel", "ΔE = C_sIω²", ""]], "keywords": ["shaft design DE-Goodman", "critical speed", "flywheel coefficient of fluctuation", "key"], "examples": [{"title": "Critical speed", "problem": "A 250 lb disk sits at the center of a Ø1.5 in steel shaft (E = 30×10⁶ psi) on bearings 48 in apart. Find n_c.", "steps": ["I = π(1.5)⁴/64 = 0.2485 in⁴; δ = WL³/48EI = 0.0773 in.", "n_c = (30/π)√(386.1/δ) = 675 rpm."], "answer": "675 rpm"}], "traps": ["Using g = 32.2 ft/s² with δ in inches.", "Leaving out K_f at shoulders.", "Applying the mean-torsion term to the alternating stress."], "cheat": ["DE-Goodman d formula", "n_c = (30/π)√(g/δ)", "ΔE = C_sIω²", "Check slopes at bearings"], "area": 4}, {"code": "4.E", "title": "Motors and Engines", "weak": false, "concepts": ["Induction motor: synchronous speed n_s = 120f/p (p = poles). Slip s = (n_s − n)/n_s.", "Three-phase input: P = √3·V·I·pf. Output = η × input. T = 63,025hp/n.", "Engines: brake power = 2πNT. Thermal efficiency = output/fuel energy. BSFC = fuel rate/brake power."], "formulas": [["Sync speed", "n_s = 120f/p", ""], ["Slip", "n = n_s(1 − s)", ""], ["3-phase power", "P = √3·V·I·pf", ""], ["Line current", "I = hp·746/(√3·V·η·pf)", ""]], "keywords": ["induction motor slip", "synchronous speed", "three phase power", "motor efficiency"], "examples": [{"title": "Motor current", "problem": "A 25 hp, 460 V three-phase motor has η = 0.90 and pf = 0.85. Find the line current.", "steps": ["I = 25(746)/(√3·460·0.90·0.85) = 30.6 A."], "answer": "30.6 A"}], "traps": ["Using poles/2 incorrectly (n_s = 120f/p with p = total poles).", "Forgetting efficiency when going from output to input power."], "cheat": ["n_s = 120f/p", "n = n_s(1 − s)", "P = √3VI·pf", "T = 63,025hp/n"], "area": 4}, {"code": "5.A", "title": "Pressurized Vessels and Piping", "weak": false, "concepts": ["Thin wall (t < D/20): hoop σ_t = pD/(2t), longitudinal σ_L = pD/(4t). Sphere: σ = pD/(4t).", "Thick wall (Lamé): σ_t = [p_ir_i² − p_or_o² + r_i²r_o²(p_i − p_o)/r²]/(r_o² − r_i²). Internal pressure only: the maximum is at r_i, σ_t = p(r_o² + r_i²)/(r_o² − r_i²).", "ASME VIII Div. 1 shell: t = PR/(SE − 0.6P), with R the inside radius and E the joint efficiency."], "formulas": [["Hoop", "σ_t = pD/(2t)", ""], ["Longitudinal", "σ_L = pD/(4t)", ""], ["Lamé (internal)", "σ_t,max = p(r_o² + r_i²)/(r_o² − r_i²)", ""], ["ASME shell", "t = PR/(SE − 0.6P)", ""]], "keywords": ["thin-walled pressure vessel", "Lamé thick-walled cylinder", "ASME Section VIII thickness"], "examples": [{"title": "ASME shell thickness", "problem": "R = 30 in, P = 250 psi, S = 20,000 psi, E = 0.85. Find t.", "steps": ["t = 250(30)/(20,000·0.85 − 0.6·250) = 0.445 in (add the corrosion allowance)."], "answer": "0.445 in"}], "traps": ["Using the radius in pD/2t (D is the diameter).", "Using the thin-wall formula when t/r > 0.1."], "cheat": ["σ_t = pD/2t; σ_L = pD/4t", "Lamé max at the bore", "t = PR/(SE − 0.6P)"], "area": 5}, {"code": "5.B", "title": "Hydraulic and Pneumatic Components", "weak": false, "concepts": ["Cylinder force F = pA. On retraction use the annulus A = π(D² − d²)/4. Speed v = Q/A.", "Hydraulic power: hp = Q(gpm)·p(psi)/1,714. Input = output/η.", "Pneumatics: the air is compressible, so use absolute pressure in gas-law calculations."], "formulas": [["Force", "F = pA", ""], ["Speed", "v = Q/A (231 in³/gal)", ""], ["Power", "hp = Q·p/1,714", ""]], "keywords": ["hydraulic cylinder force", "hydraulic power 1714", "pump efficiency"], "examples": [{"title": "Cylinder speed and force", "problem": "A Ø3 in bore cylinder at 1,500 psi is supplied with 12 gpm. Find the extension force and speed.", "steps": ["A = 7.069 in²; F = 10,603 lb.", "v = 12(231)/60/7.069 = 6.54 in/s."], "answer": "F ≈ 10,603 lb; v ≈ 6.54 in/s"}], "traps": ["Using the full bore area on retraction.", "Gauge pressure in gas laws."], "cheat": ["F = pA", "v = Q/A", "hp = Qp/1,714"], "area": 5}, {"code": "5.C", "title": "Beams, Trusses, and Frames (Statics)", "weak": true, "concepts": ["Free-body diagram first: isolate the body, show every external force and moment (weight, supports, friction). Unknown reactions: pin = 2 forces, roller = 1, fixed = 2 forces + 1 moment.", "Equilibrium: ΣF_x = 0, ΣF_y = 0, ΣM = 0. Take moments about the point with the most unknowns.", "Trusses: method of joints (ΣF = 0 at each pin; start where there are ≤ 2 unknowns) or method of sections (cut ≤ 3 members, then take moments). Zero-force members: at an unloaded joint where two members are collinear, the third member is zero.", "Friction: F ≤ μ_sN. Impending motion means F = μ_sN. Belt/capstan: T₁/T₂ = e^(μθ).", "Centroids and moments of inertia of composites: x̄ = ΣA x/ΣA, then I = Σ(I_c + Ad²)."], "formulas": [["Equilibrium", "ΣF = 0 ; ΣM = 0", ""], ["Friction", "F = μN (impending)", ""], ["Capstan", "T₁ = T₂e^(μθ)", "θ rad"], ["Centroid", "ȳ = ΣAᵢyᵢ/ΣAᵢ", ""], ["Parallel axis", "I = Σ(I_c + Ad²)", ""], ["Two-force member", "force along the line joining its pins", ""]], "keywords": ["equilibrium", "method of joints", "method of sections", "zero-force member", "friction", "centroid", "parallel axis"], "examples": [{"title": "Beam reaction", "problem": "A 12 ft simple beam carries 9,000 lb at 4 ft from support A. Find R_A and R_B.", "steps": ["ΣM_B = 0: R_A(12) = 9,000(8).", "R_A = 6,000 lb; R_B = 9,000 − 6,000 = 3,000 lb."], "answer": "R_A = 6,000 lb, R_B = 3,000 lb"}, {"title": "Ladder friction", "problem": "A uniform ladder leans at 60° from the floor against a smooth wall. Find the minimum μ at the floor.", "steps": ["Smooth wall: horizontal reaction N_w only. Floor: N = W, F = N_w.", "ΣM about the foot: N_w·L sin60 = W(L/2)cos60 → N_w = W/(2 tan60).", "μ_min = N_w/N = 1/(2 tan60°) = 0.289."], "answer": "0.289"}, {"title": "Truss member", "problem": "Two members meet at an apex at 40° to the horizontal and carry 10,000 lb vertically. Find the force in each.", "steps": ["2F sin40° = 10,000 → F = 7,779 lb (compression)."], "answer": "7,779 lb"}], "traps": ["Leaving the friction force or the weight off the FBD.", "Adding a 'ma' force to a static FBD.", "Using cos where sin belongs (draw the angle).", "Taking moments about a point where the unknowns do not drop out."], "cheat": ["FBD → ΣF = 0, ΣM = 0", "Pin 2, roller 1, fixed 3 unknowns", "Zero-force: 2 collinear + 1 at an unloaded joint", "F = μN impending", "T₁/T₂ = e^(μθ)", "ȳ = ΣAy/ΣA; I = Σ(I_c + Ad²)"], "area": 5}, {"code": "5.D", "title": "Springs", "weak": false, "concepts": ["Helical compression spring: k = Gd⁴/(8D³N_a). Spring index C = D/d (4–12 is good).", "Stress: τ = K_W·8FD/(πd³), with Wahl K_W = (4C − 1)/(4C − 4) + 0.615/C (or Bergsträsser K_B = (4C + 2)/(4C − 3)).", "Series springs: 1/k = Σ1/kᵢ. Parallel: k = Σkᵢ. Energy U = ½kx².", "Spring fatigue: Zimmerli data with torsional Goodman. Surge frequency: avoid resonance with the operating frequency."], "formulas": [["Rate", "k = Gd⁴/(8D³N)", ""], ["Stress", "τ = K·8FD/(πd³)", ""], ["Wahl", "K = (4C − 1)/(4C − 4) + 0.615/C", ""], ["Series/parallel", "1/k = Σ1/kᵢ ; k = Σkᵢ", ""]], "keywords": ["helical spring rate", "Wahl factor", "spring index", "springs in series"], "examples": [{"title": "Spring rate", "problem": "Music wire G = 11.5×10⁶ psi, d = 0.148 in, D = 1.5 in, N_a = 8. Find k.", "steps": ["k = 11.5×10⁶(0.148)⁴/(8·1.5³·8) = 25.5 lb/in."], "answer": "25.5 lb/in"}], "traps": ["Using the outside diameter for D (use the mean coil diameter).", "Leaving out the curvature factor."], "cheat": ["k = Gd⁴/8D³N", "τ = K8FD/πd³", "Series 1/k = Σ1/k"], "area": 5}, {"code": "5.E", "title": "Vibrating Systems", "weak": true, "concepts": ["SDOF: ω_n = √(k/m), f_n = ω_n/2π. Static deflection shortcut: ω_n = √(g/δ_st), f_n ≈ 3.13/√δ(in) Hz.", "Damping: c_c = 2√(km) = 2mω_n, ζ = c/c_c. Damped frequency ω_d = ω_n√(1 − ζ²). Log decrement δ = (1/n)ln(x₀/x_n), ζ = δ/√(4π² + δ²).", "Forced response: X = (F₀/k)/√[(1 − r²)² + (2ζr)²], with r = ω/ω_n. Resonance is near r = 1.", "Transmissibility TR = √[(1 + (2ζr)²)/((1 − r²)² + (2ζr)²)]. Isolation (TR < 1) needs r > √2. Above √2, damping INCREASES TR, and softer springs or more mass help. Undamped: TR = 1/(r² − 1).", "Rotating unbalance: X = (m_e e/M)r²/√[(1 − r²)² + (2ζr)²].", "Equivalent systems: springs in series or parallel. Cantilever k = 3EI/L³; simply supported center k = 48EI/L³. Torsional k_t = GJ/L, ω_n = √(k_t/J_mass). Compound pendulum ω_n = √(mgd/I_O)."], "formulas": [["Natural frequency", "ω_n = √(k/m) ; f = ω_n/2π", ""], ["Static deflection", "ω_n = √(g/δ_st)", ""], ["Damping ratio", "ζ = c/(2√(km))", ""], ["Damped", "ω_d = ω_n√(1 − ζ²)", ""], ["Log decrement", "δ = (1/n)ln(x₀/x_n) ; ζ ≈ δ/2π", ""], ["Amplitude", "X = (F₀/k)/√[(1 − r²)² + (2ζr)²]", ""], ["Transmissibility", "TR = √[(1 + (2ζr)²)/((1 − r²)² + (2ζr)²)]", ""], ["Beam stiffness", "cantilever 3EI/L³ ; SS center 48EI/L³", ""]], "keywords": ["natural frequency", "damping ratio", "logarithmic decrement", "transmissibility", "vibration isolation", "rotating unbalance", "forced vibration"], "examples": [{"title": "Damping and frequency", "problem": "m = 10 kg, k = 100 kN/m, c = 150 N·s/m. Find f_n, ζ and f_d.", "steps": ["ω_n = √(100,000/10) = 100.0 rad/s → f_n = 15.92 Hz.", "c_c = 2√(km) = 2,000 N·s/m; ζ = 150/2,000 = 0.075.", "f_d = f_n√(1 − ζ²) = 15.87 Hz (practically the same)."], "answer": "f_n = 15.92 Hz, ζ = 0.075"}, {"title": "Isolation", "problem": "A machine on mounts runs at r = 3 with ζ = 0.1. Find TR. Would more damping help?", "steps": ["TR = √[(1 + 0.6²)/((1 − 9)² + 0.6²)] = 0.1454.", "No. Above r = √2, extra damping raises TR."], "answer": "TR ≈ 0.145"}, {"title": "Isolator static deflection", "problem": "Undamped mounts must give TR = 0.20 at 1,800 rpm. Find the required static deflection.", "steps": ["r² = 1/TR + 1 = 6 → r = 2.449.", "ω = 1,800·2π/60 = 188.5 rad/s; ω_n = ω/r = 77.0 rad/s.", "δ = g/ω_n² = 386.1/5922 = 0.0652 in."], "answer": "0.065 in"}], "traps": ["Mixing Hz and rad/s (ω = 2πf).", "Thinking damping always helps isolation (it hurts above √2).", "Leaving k in kN/m or N/mm while m is in kg.", "Using the series formula for parallel springs."], "cheat": ["ω_n = √(k/m) = √(g/δ)", "ζ = c/2√(km)", "ω_d = ω_n√(1 − ζ²)", "ζ ≈ ln(x₀/x_n)/(2πn)", "TR < 1 only for r > √2", "Undamped TR = 1/(r² − 1)", "k: cantilever 3EI/L³, SS 48EI/L³"], "area": 5}, {"code": "5.F", "title": "Basic Machines and Mechanisms (Dynamics)", "weak": true, "concepts": ["Kinematics: constant acceleration gives v = v₀ + at, s = v₀t + ½at², v² = v₀² + 2as. Rotation is the same with θ, ω, α, and v = rω, a_t = rα, a_n = rω².", "Kinetics: ΣF = ma and ΣM_G = I_Gα. Draw the FBD and the kinetic diagram.", "Work–energy: T₁ + ΣU = T₂, with T = ½mv² + ½Iω². Spring energy ½kx², gravity mgh, friction work μNd.", "Impulse–momentum: mv₁ + ∫F dt = mv₂. Impact: momentum is conserved; e = (v₂′ − v₁′)/(v₁ − v₂).", "Rolling without slip: a = g sinθ/(1 + I/(mr²)). Hoop: I = mr². Solid disk: ½mr². Sphere: 0.4mr².", "Mechanisms: mechanical advantage, linkages (Grashof), cams, and gear/belt speed ratios."], "formulas": [["Kinematics", "v² = v₀² + 2as ; s = v₀t + ½at²", ""], ["Newton", "ΣF = ma ; ΣM = Iα", ""], ["Work–energy", "½mv₁² + ΣU = ½mv₂²", ""], ["Restitution", "e = (v₂′ − v₁′)/(v₁ − v₂)", ""], ["Rolling", "a = g sinθ/(1 + k²/r²)", ""], ["Centripetal", "F = mrω² = mv²/r", ""], ["Braking distance", "d = v²/(2μg)", ""]], "keywords": ["kinematics", "Newton's second law", "work-energy", "impulse momentum", "coefficient of restitution", "rolling without slipping", "mass moment of inertia"], "examples": [{"title": "Crate on an incline", "problem": "A crate is released on a 25° incline with μ_k = 0.15. Find a and the speed after 4 m.", "steps": ["a = g(sin25° − 0.15cos25°) = 2.81 m/s².", "v = √(2as) = √(2·2.81·4) = 4.74 m/s."], "answer": "a = 2.81 m/s², v = 4.74 m/s"}, {"title": "Impact", "problem": "A 3 kg ball at 12 m/s hits a stationary 8 kg ball, e = 0.8. Find v₂′.", "steps": ["Momentum: 36 = 3v₁′ + 8v₂′. Restitution: v₂′ − v₁′ = 9.6.", "v₂′ = m₁v₁(1 + e)/(m₁ + m₂) = 3(12)(1.8)/11 = 5.89 m/s."], "answer": "5.89 m/s"}, {"title": "Spinning up a rotor", "problem": "I = 4 kg·m², net torque 50 N·m. Time to reach 1,200 rpm?", "steps": ["ω = 1,200·2π/60 = 125.7 rad/s; α = T/I = 12.5 rad/s².", "t = ω/α = 10.05 s."], "answer": "10.1 s"}], "traps": ["Forgetting the rotational KE of rolling bodies.", "Treating rpm as rad/s.", "Assuming energy is conserved in an impact (only momentum is).", "Getting the friction direction wrong (it opposes relative motion)."], "cheat": ["v² = v₀² + 2as", "ΣF = ma, ΣM = Iα", "T = ½mv² + ½Iω²", "e = sep/approach", "Rolling a = g sinθ/(1 + I/mr²)", "ω = 2πn/60"], "area": 5}, {"code": "6.A", "title": "Manufacturing Methods", "weak": false, "concepts": ["Machining: spindle speed N = 12V/(πD) (V in sfm, D in in). Feed rate = f·N. Time = L/(fN). Taylor tool life VTⁿ = C.", "Process choice: casting (complex shapes, lower strength), forging (good grain flow, fatigue strength), machining (precision), additive (complex shapes, low volume), thread rolling (cold work, better fatigue).", "Heat treatment: annealing (soft), normalizing, quench and temper, case hardening (carburizing or nitriding)."], "formulas": [["Spindle speed", "N = 12V/(πD)", ""], ["Cutting time", "t = L/(fN)", ""], ["Taylor", "VTⁿ = C", ""], ["MRR (turning)", "MRR = 12V·f·d", "in³/min"]], "keywords": ["cutting speed", "Taylor tool life", "machining time", "manufacturing processes"], "examples": [{"title": "Taylor tool life", "problem": "n = 0.25, C = 400. Find T at V = 300 ft/min.", "steps": ["T = (400/300)^(1/0.25) = 3.16 min."], "answer": "3.16 min"}], "traps": ["Leaving out the 12 in N = 12V/πD.", "Inverting the exponent in Taylor (use 1/n)."], "cheat": ["N = 12V/πD", "t = L/fN", "T = (C/V)^(1/n)"], "area": 6}, {"code": "6.B", "title": "Fits and Tolerances", "weak": false, "concepts": ["Hole-basis system: the hole lower limit equals basic size (H). Max clearance = largest hole − smallest shaft. Min clearance (or max interference) = smallest hole − largest shaft.", "ANSI B4.1 classes: RC running, LC locational clearance, LT transition, LN locational interference, FN force/shrink. ISO: H7/g6 sliding, H7/h6 locational, H7/p6 interference, H7/s6 drive.", "Tolerance stack: worst case T = ΣTᵢ; statistical (RSS) T = √ΣTᵢ²."], "formulas": [["Max clearance", "C_max = hole_max − shaft_min", ""], ["Min clearance", "C_min = hole_min − shaft_max (negative = interference)", ""], ["Worst case", "T = Σtᵢ", ""], ["RSS", "T = √Σtᵢ²", ""]], "keywords": ["limits and fits", "ANSI B4.1", "ISO 286", "tolerance stack-up RSS"], "examples": [{"title": "Stack-up", "problem": "Four parts at ±0.002, ±0.003, ±0.002, ±0.004 in. Find the worst-case and RSS tolerances.", "steps": ["Worst case = ±0.011 in.", "RSS = √(4 + 9 + 4 + 16)×10⁻³ = ±0.0057 in."], "answer": "±0.011 (WC), ±0.0057 (RSS)"}], "traps": ["Swapping max and min clearance.", "Using RSS when the question asks for worst case."], "cheat": ["C_max = H_max − s_min", "C_min = H_min − s_max", "WC Σt; RSS √Σt²", "FN = force fit"], "area": 6}, {"code": "6.C", "title": "Codes and Standards", "weak": false, "concepts": ["Know which code covers what:", "ASME BPVC Section VIII: unfired pressure vessels. Section I: power boilers. ASME B31.1: power piping. B31.3: process piping.", "ASME Y14.5: GD&T. Y14.100: drawing practice. AWS A2.4: weld symbols. AWS D1.1: structural steel welding.", "AGMA 2001: gear rating. ANSI/ABMA 9/11 and ISO 281: bearing ratings. SAE J429 and ASTM A325/A490: bolt grades. ASTM E8: tension test. ISO 286 and ANSI B4.1: fits.", "The exam may supply excerpts of specific standards. Check the last page of the NCEES MDM specification for the current list."], "formulas": [["(no formulas)", "Recognition topic. Know the scope of each code.", ""]], "keywords": ["ASME Section VIII", "B31.3", "Y14.5", "AWS D1.1", "AGMA", "ABMA"], "examples": [{"title": "Identify the code", "problem": "You are designing process piping in a refinery. Which code governs?", "steps": ["Process piping falls under ASME B31.3 (power-plant piping is B31.1)."], "answer": "ASME B31.3"}], "traps": ["Confusing B31.1 (power) with B31.3 (process).", "Confusing AWS A2.4 (symbols) with D1.1 (structural welding)."], "cheat": ["BPVC VIII vessels", "B31.1 power / B31.3 process", "Y14.5 GD&T", "AWS D1.1 welding", "AGMA gears; ABMA bearings", "SAE J429 bolts"], "area": 6}, {"code": "6.D", "title": "Computational Methods", "weak": false, "concepts": ["Linear interpolation from property tables: y = y₁ + (y₂ − y₁)(x − x₁)/(x₂ − x₁).", "Root finding: Newton–Raphson x₁ = x₀ − f(x₀)/f′(x₀). Bisection is slower but always converges.", "Numerical integration: trapezoid; Simpson's 1/3 rule (even number of intervals) is exact for cubics.", "FEA: refine the mesh where gradients are high. Sharp re-entrant corners are singularities, so model the real fillet. Check reactions against the hand-calculated loads."], "formulas": [["Interpolation", "y = y₁ + (y₂ − y₁)(x − x₁)/(x₂ − x₁)", ""], ["Newton–Raphson", "x_{k+1} = x_k − f/f′", ""], ["Simpson 1/3", "∫ ≈ (h/3)[f₀ + 4f₁ + 2f₂ + … + f_n]", ""], ["Trapezoid", "∫ ≈ (h/2)[f₀ + 2f₁ + … + f_n]", ""]], "keywords": ["linear interpolation", "Newton-Raphson", "Simpson's rule", "finite element"], "examples": [{"title": "Newton–Raphson", "problem": "Find the root of f(x) = x³ − 2x − 5 starting at x₀ = 2 (one iteration).", "steps": ["f(2) = −1; f′(x) = 3x² − 2 = 10.", "x₁ = 2 − (−1)/10 = 2.1."], "answer": "2.1 (true root ≈ 2.0946)"}], "traps": ["Using Simpson's rule with an odd number of intervals.", "Inverting the slope in Newton's method."], "cheat": ["Interp: y₁ + Δy·(x − x₁)/Δx", "N–R: x − f/f′", "Simpson: h/3[1 4 2 4 … 1]", "FEA: singular corners do not converge"], "area": 6}, {"code": "6.E", "title": "Instrumentation, Testing, Inspection, and Quality", "weak": false, "concepts": ["Measurement: the instrument resolution should be about 1/10 of the tolerance. A micrometer reads 0.0001 in; a caliper reads 0.001 in.", "Strain gage: ε = (ΔR/R)/GF.", "Process capability: C_p = (USL − LSL)/6σ; C_pk = min(USL − μ, μ − LSL)/3σ. 1.33 or more is good.", "Control charts: X̄ chart limits X̄ ± A₂R̄; R chart limits D₃R̄ and D₄R̄.", "NDT: UT and RT find subsurface flaws. Dye penetrant finds surface-breaking flaws only. Magnetic particle finds surface and near-surface flaws (ferromagnetic parts only)."], "formulas": [["Strain gage", "ε = (ΔR/R)/GF", ""], ["Cp", "C_p = (USL − LSL)/(6σ)", ""], ["Cpk", "C_pk = min(USL − μ, μ − LSL)/(3σ)", ""], ["X̄ chart", "UCL = X̄ + A₂R̄", ""]], "keywords": ["process capability Cpk", "control chart", "strain gage factor", "nondestructive testing"], "examples": [{"title": "Cpk", "problem": "Limits 25.00–25.10 mm, μ = 25.035, σ = 0.010. Find C_p and C_pk.", "steps": ["C_p = 0.10/0.06 = 1.67.", "C_pk = min(0.065, 0.035)/0.03 = 1.17 (not centered)."], "answer": "C_p = 1.67, C_pk = 1.17"}], "traps": ["Using C_p when the process is off center.", "Expecting dye penetrant to find internal flaws."], "cheat": ["ε = (ΔR/R)/GF", "C_pk = min(...)/3σ", "UCL = X̄ + A₂R̄", "UT/RT subsurface; PT surface only"], "area": 6}, {"code": "6.F", "title": "Chemical Processes (Corrosion, Coatings, Treatments)", "weak": false, "concepts": ["Galvanic corrosion: the more anodic metal corrodes (Mg, Zn, Al, steel, … Cu, stainless (passive), Ti, graphite). Avoid a small anode with a large cathode; isolate dissimilar metals.", "Protection: coatings, galvanizing (zinc as a sacrificial anode), cathodic protection, inhibitors, material selection.", "Hydrogen embrittlement: high-strength steels after plating or pickling. Bake after plating.", "Surface treatments: carburizing and nitriding (hard case), shot peening (compressive residual stress), anodizing (aluminum)."], "formulas": [["(mostly concept)", "Galvanic series order; area ratio effect", ""]], "keywords": ["galvanic series", "corrosion protection", "hydrogen embrittlement", "surface treatment"], "examples": [{"title": "Galvanic pair", "problem": "Aluminum rivets in a stainless panel in seawater. What happens and how do you fix it?", "steps": ["Aluminum is anodic and the rivet area is small: severe rivet corrosion.", "Fix: use stainless rivets (large anode, small cathode), isolate the metals, or coat the cathode."], "answer": "The rivets corrode; change the material or isolate"}], "traps": ["Coating only the anode (any holiday then corrodes fast). Coat the cathode, or both."], "cheat": ["Anode corrodes", "Small anode/large cathode = bad", "Zinc protects steel sacrificially", "Bake after plating"], "area": 6}];